// Entrega a mensagem do broadcast pelo Telegram (Bot API oficial). Contatos
// que ainda não vincularam o chat (não abriram o bot e compartilharam o
// número) saem direto como falha, com o motivo registrado (RF-06).
// O anexo, se houver, é enviado nos próximos nós.
const body = $('Webhook').first().json.body;
const base = $env.TELEGRAM_API_URL || 'https://api.telegram.org';
const token = $env.TELEGRAM_BOT_TOKEN;
const callbackUrl = (body.callbackUrl || '')
  .replace('127.0.0.1', 'host.docker.internal')
  .replace('localhost', 'host.docker.internal');

// O token só existe no ambiente do N8N; nunca pode ir para o detalhe do log.
const redact = (text) => (token ? String(text ?? '').split(token).join('***') : String(text ?? ''));

const results = [];
for (const c of body.contacts || []) {
  let status = 'falha';
  let detail;
  let messageId = null;
  if (!token) {
    detail = 'TELEGRAM_BOT_TOKEN não configurado no N8N.';
  } else if (!c.telegramChatId) {
    detail = 'Contato ainda não vinculou o Telegram (abrir o bot e compartilhar o número).';
  } else {
    try {
      const res = await this.helpers.httpRequest({
        method: 'POST',
        url: `${base}/bot${token}/sendMessage`,
        body: { chat_id: c.telegramChatId, text: body.message },
        json: true,
      });
      status = res.ok ? 'enviado' : 'falha';
      messageId = res.ok ? res.result.message_id : null;
      detail = res.ok ? `Entregue no Telegram (mensagem ${messageId}).` : res.description;
    } catch (err) {
      detail = `Telegram recusou o envio: ${err.description || err.message}`;
    }
  }
  results.push({ json: { logId: c.logId, status, detail: redact(detail), callbackUrl, chatId: c.telegramChatId || null, messageId } });
}
return results;

// Anexo da oportunidade (PDF ou imagem) vira dado binário para o nó de
// upload. O arquivo sobe uma vez só, no primeiro contato que recebeu o texto;
// os demais recebem pelo file_id devolvido pelo Telegram.
const attachment = $('Webhook').first().json.body.attachment;
const first = $input.all().find((i) => i.json.status === 'enviado');
if (!attachment || !attachment.base64 || !first) return [{ json: { skip: true } }];

const isPhoto = String(attachment.mimeType).startsWith('image/');
return [{
  json: { skip: false, isPhoto, logId: first.json.logId, chatId: first.json.chatId, method: isPhoto ? 'sendPhoto' : 'sendDocument', field: isPhoto ? 'photo' : 'document' },
  binary: { data: { data: attachment.base64, mimeType: attachment.mimeType, fileName: attachment.fileName || 'anexo' } },
}];

// Junta o resultado do anexo ao status de cada contato: o primeiro recebeu
// o upload; os demais recebem pelo file_id. Se o anexo falhar, a mensagem
// continua entregue e o motivo vai para o detalhe do log.
const base = $env.TELEGRAM_API_URL || 'https://api.telegram.org';
const token = $env.TELEGRAM_BOT_TOKEN;
const redact = (text) => (token ? String(text ?? '').split(token).join('***') : String(text ?? ''));

const items = $('Enviar pelo Telegram').all().map((i) => ({ ...i.json }));
const prep = $('Preparar anexo').first().json;
const done = (list) => list.map(({ chatId, messageId, ...j }) => ({ json: j }));
if (prep.skip) return done(items);

const up = $input.first().json;
let fileId = null;
let uploadMessageId = null;
let uploadError = null;
if (up && up.ok && up.result) {
  uploadMessageId = up.result.message_id;
  fileId = prep.isPhoto ? up.result.photo[up.result.photo.length - 1].file_id : up.result.document.file_id;
} else {
  uploadError = redact((up && up.error && (up.error.message || up.error.description)) || (up && up.description) || 'falha no upload');
}

for (const j of items) {
  if (j.status !== 'enviado') continue;
  if (j.logId === prep.logId) {
    j.detail = uploadMessageId
      ? `Entregue no Telegram com o anexo (mensagens ${j.messageId} e ${uploadMessageId}).`
      : `Mensagem entregue (${j.messageId}), mas o anexo não foi enviado: ${uploadError}`;
    continue;
  }
  if (!fileId) {
    j.detail = `Mensagem entregue (${j.messageId}), mas o anexo não foi enviado: ${uploadError}`;
    continue;
  }
  try {
    const res = await this.helpers.httpRequest({
      method: 'POST',
      url: `${base}/bot${token}/${prep.method}`,
      body: { chat_id: j.chatId, [prep.field]: fileId },
      json: true,
    });
    j.detail = res.ok
      ? `Entregue no Telegram com o anexo (mensagens ${j.messageId} e ${res.result.message_id}).`
      : `Mensagem entregue (${j.messageId}), mas o anexo não foi enviado: ${res.description}`;
  } catch (err) {
    j.detail = redact(`Mensagem entregue (${j.messageId}), mas o anexo não foi enviado: ${err.description || err.message}`);
  }
}
return done(items);
